// Normalize any source payload into a flat list of items.
// Edit the mapping below to match YOUR source's field names.
const input = $input.first().json;

// Try common shapes: {hits:[...]}, {items:[...]}, [...], {data:[...]}
const raw = input.hits || input.items || input.data || (Array.isArray(input) ? input : []);

const out = raw.map((r) => {
  const id = String(r.objectID ?? r.id ?? r.guid ?? r.url ?? '');
  return {
    json: {
      id,
      title: r.title ?? r.story_title ?? r.name ?? '(no title)',
      url: r.url ?? r.story_url ?? r.link ?? '',
      author: r.author ?? r.by ?? '',
      points: Number(r.points ?? r.score ?? 0),
      comments: Number(r.num_comments ?? r.comments ?? 0),
      createdAt: r.created_at ?? r.date ?? new Date().toISOString(),
      fetchedAt: new Date().toISOString()
    }
  };
}).filter((x) => x.json.id && x.json.title);

return out;

