// Merge the AI response back onto the item and derive a routing tag.
const item = $json;

let score = 0, reason = '';
try {
  const content = item.choices?.[0]?.message?.content ?? '{}';
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  score = Number(parsed.score ?? 0);
  reason = String(parsed.reason ?? '');
} catch (e) {
  reason = 'parse_error: ' + e.message;
}

// Pull the original fields forward from the AI-Score input item.
const src = $('Filter Relevant').item.json;

const tier = score >= 70 ? 'HOT' : score >= 40 ? 'WARM' : 'COLD';

return [{
  json: {
    ...src,
    aiScore: score,
    aiReason: reason,
    tier
  }
}];
